def c_string(text):
    out = '"'
    for b in text.encode('utf-8'):
        c = chr(b)
        if c in '"\\':
            out += '\\' + c
        elif 32 <= b < 127:
            out += c
        else:
            out += '\\%03o' % b  # octal escapes never swallow a following hex digit
    return out + '"'


def java_string(text):
    out = '"'
    for ch in text:
        if ch in '"\\':
            out += '\\' + ch
        elif 32 <= ord(ch) < 127:
            out += ch
        else:
            out += '\\u%04x' % ord(ch)
    return out + '"'


def generate(root):
    """Writes src/lang_table.inc and java/com/tremu/app/LangTable.java under root."""
    from lang_ja import JA
    missing = [row[0] for row in STRINGS if row[0] not in JA]
    assert not missing, 'no Japanese for: %r' % missing
    rows = [row + (JA[row[0]],) for row in STRINGS]
    seen = set()
    for row in rows:
        assert len(row) == len(CODES), row[0]
        assert row[0] not in seen, 'duplicate: ' + row[0]
        seen.add(row[0])
    c = ['/* Generated by tools/lang.py: do not edit. */']
    c.append('static const char *const LANGUAGE_NAMES[] = {%s};' % ', '.join(c_string(n) for n in LANGUAGES))
    c.append('static const char *const TABLE[][%d] = {' % len(CODES))
    for row in rows:
        c.append('    {%s},' % ', '.join(c_string(t) for t in row))
    c.append('};')
    (root / 'src' / 'lang_table.inc').write_text('\n'.join(c) + '\n', encoding='utf-8')
    j = ['// Generated by tools/lang.py: do not edit.', 'package com.tremu.app;', '',
         'final class LangTable {', '    private LangTable() {}', '',
         '    static final String[] CODES = {%s};' % ', '.join(java_string(x) for x in CODES),
         '    static final String[][] TABLE = {']
    for row in rows:
        j.append('        {%s},' % ', '.join(java_string(t) for t in row))
    j += ['    };', '}']
    (root / 'java' / 'com' / 'tremu' / 'app' / 'LangTable.java').write_text('\n'.join(j) + '\n', encoding='utf-8')
